set_var "MONITORING_CONTEXT" "$MONITORING_CONTEXT" "setup_monitoring_context"

# Node: basic_circuit_breaker
# Node: basic_circuit_breaker (basic_circuit_breaker)
execute_circuit_breaker_basic_circuit_breaker() {
    log_step "⚡ Circuit Breaker: Basic Service Protection Circuit Breaker"
    local failure_threshold=$(echo "$(get_var "FAILURE_THRESHOLD" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "5")
    local timeout_duration=$(echo "$(get_var "TIMEOUT_DURATION" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "60")
    local success_threshold=$(echo "$(get_var "SUCCESS_THRESHOLD" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "3")
    local monitor_window=$(echo "$(get_var "MONITOR_WINDOW" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "300")
    
    # Circuit breaker state files
    local state_dir="${FLOWSH_TEMP_DIR:-/tmp}/circuit_breaker_basic_circuit_breaker"
    local state_file="$state_dir/state"
    local failure_file="$state_dir/failures"
    local success_file="$state_dir/successes"
    local last_failure_file="$state_dir/last_failure"
    
    # Ensure state directory exists
    mkdir -p "$state_dir"
    register_temp_file "$state_dir"
    
    # Initialize circuit breaker state if not exists
    if [[ ! -f "$state_file" ]]; then
        echo "CLOSED" > "$state_file"
        echo "0" > "$failure_file"
        echo "0" > "$success_file"
        echo "0" > "$last_failure_file"
    fi
    
    local current_state=$(cat "$state_file")
    local failure_count=$(cat "$failure_file")
    local success_count=$(cat "$success_file")
    local last_failure_time=$(cat "$last_failure_file")
    local current_time=$(date +%s)
    
    log_info "Circuit breaker state: $current_state (failures: $failure_count, successes: $success_count)"
    
    # Clean up old failures outside monitor window
    if [[ $((current_time - last_failure_time)) -gt $monitor_window ]]; then
        echo "0" > "$failure_file"
        failure_count=0
        log_debug "Reset failure count - outside monitor window"
    fi
    
    case "$current_state" in
        "CLOSED")
            # Normal operation - allow calls
            log_debug "Circuit CLOSED - executing protected operation"
            
            if execute_circuit_breaker_operation; then
                # Success - reset failure count
                echo "0" > "$failure_file"
                echo "0" > "$success_file"
                log_success "Circuit breaker operation succeeded"
                return 0
            else
                # Failure - increment failure count
                failure_count=$((failure_count + 1))
                echo "$failure_count" > "$failure_file"
                echo "$current_time" > "$last_failure_file"
                
                log_warning "Circuit breaker operation failed (failure $failure_count/$failure_threshold)"
                
                if [[ $failure_count -ge $failure_threshold ]]; then
                    echo "OPEN" > "$state_file"
                    log_error "Circuit breaker OPENED - failure threshold reached"
                    set_workflow_var "circuit_breaker_state" "OPEN"
                    set_workflow_var "circuit_breaker_opened_at" "$current_time"
                fi
                
                return 1
            fi
            ;;
        "OPEN")
            # Circuit is open - check if timeout has passed
            local time_since_open=$((current_time - last_failure_time))
            
            if [[ $time_since_open -ge $timeout_duration ]]; then
                # Timeout passed - move to half-open
                echo "HALF_OPEN" > "$state_file"
                echo "0" > "$success_file"
                log_info "Circuit breaker moved to HALF_OPEN - testing recovery"
                set_workflow_var "circuit_breaker_state" "HALF_OPEN"
                
                # Try the operation
                if execute_circuit_breaker_operation; then
                    success_count=1
                    echo "$success_count" > "$success_file"
                    log_info "Half-open test succeeded (success 1/$success_threshold)"
                    
                    if [[ $success_count -ge $success_threshold ]]; then
                        echo "CLOSED" > "$state_file"
                        echo "0" > "$failure_file"
                        echo "0" > "$success_file"
                        log_success "Circuit breaker CLOSED - recovery complete"
                        set_workflow_var "circuit_breaker_state" "CLOSED"
                    fi
                    
                    return 0
                else
                    # Failed during half-open - back to open
                    echo "OPEN" > "$state_file"
                    echo "$current_time" > "$last_failure_file"
                    log_error "Half-open test failed - circuit breaker back to OPEN"
                    set_workflow_var "circuit_breaker_state" "OPEN"
                    return 1
                fi
            else
                # Still in timeout period - fail fast
                local remaining_time=$((timeout_duration - time_since_open))
                log_warning "Circuit breaker OPEN - failing fast (retry in ${remaining_time}s)"
                set_workflow_var "circuit_breaker_retry_in" "$remaining_time"
                return 1
            fi
            ;;
        "HALF_OPEN")
            # Testing recovery - limited calls allowed
            log_debug "Circuit HALF_OPEN - testing recovery"
            
            if execute_circuit_breaker_operation; then
                # Success in half-open state
                success_count=$((success_count + 1))
                echo "$success_count" > "$success_file"
                log_info "Half-open test succeeded (success $success_count/$success_threshold)"
                
                if [[ $success_count -ge $success_threshold ]]; then
                    # Enough successes - close the circuit
                    echo "CLOSED" > "$state_file"
                    echo "0" > "$failure_file"
                    echo "0" > "$success_file"
                    log_success "Circuit breaker CLOSED - recovery complete"
                    set_workflow_var "circuit_breaker_state" "CLOSED"
                fi
                
                return 0
            else
                # Failure in half-open - back to open
                echo "OPEN" > "$state_file"
                echo "$current_time" > "$last_failure_file"
                log_error "Half-open test failed - circuit breaker back to OPEN"
                set_workflow_var "circuit_breaker_state" "OPEN"
                return 1
            fi
            ;;
        *)
            log_error "Invalid circuit breaker state: $current_state"
            return 1
            ;;
    esac
}
# Get current circuit breaker statistics
get_circuit_breaker_stats_basic_circuit_breaker() {
    local state_dir="${FLOWSH_TEMP_DIR:-/tmp}/circuit_breaker_basic_circuit_breaker"
    
    if [[ -d "$state_dir" ]]; then
        local current_state=$(cat "$state_dir/state" 2>/dev/null || echo "UNKNOWN")
        local failure_count=$(cat "$state_dir/failures" 2>/dev/null || echo "0")
        local success_count=$(cat "$state_dir/successes" 2>/dev/null || echo "0")
        
        cat << EOF
=== Circuit Breaker Stats (basic_circuit_breaker) ===
State: $current_state
Failures: $failure_count/$(echo "$(get_var "FAILURE_THRESHOLD" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "5")
Successes: $success_count/$(echo "$(get_var "SUCCESS_THRESHOLD" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "3")
Timeout: $(echo "$(get_var "TIMEOUT_DURATION" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "60")s
Monitor Window: $(echo "$(get_var "MONITOR_WINDOW" "basic_circuit_breaker")" | bc -l 2>/dev/null || echo "300")s
=====================================
EOF
    else
        echo "Circuit breaker not initialized"
    fi
}
execute_circuit_breaker_basic_circuit_breaker

# Node: protected_service_call
sh -c "echo 'Calling protected service: $(get_var "SERVICE_ENDPOINT" "protected_service_call")' && case '$(get_var "FAILURE_SIMULATION_MODE" "protected_service_call")' in 'stable') echo 'Service response: SUCCESS' && exit 0 ;; 'intermittent') if [ $(( RANDOM % 3 )) -eq 0 ]; then echo 'Service response: SUCCESS' && exit 0; else echo 'Service temporarily unavailable' && exit 1; fi ;; 'degraded') if [ $(( RANDOM % 2 )) -eq 0 ]; then echo 'Service response: DEGRADED SUCCESS' && exit 0; else echo 'Service degraded response failure' && exit 1; fi ;; 'failing') echo 'Service completely down' && exit 1 ;; 'recovering') if [ $(( RANDOM % 4 )) -eq 0 ]; then echo 'Service response: RECOVERY SUCCESS' && exit 0; else echo 'Service still recovering' && exit 1; fi ;; esac"

# Node: record_basic_result
# Node: record_basic_result
BASIC_CIRCUIT_RESULT=$(echo 'Basic circuit breaker completed for '"$(get_workflow_var "SERVICE_ENDPOINT" "default")"' with '"$(get_workflow_var "FAILURE_SIMULATION_MODE" "default")"' simulation')
set_var "BASIC_CIRCUIT_RESULT" "$BASIC_CIRCUIT_RESULT" "record_basic_result"

